/** Generate-time metadata registered by bundled application code (ADR-0045). */
import type { RuntimePlan } from "../spec/domain/index.js";
import { MANTLE_VERSION } from "../core/version.js";
import { emitValidators } from "./emitValidators.js";

export function emitRuntimeModule(plan: RuntimePlan): string {
  const dialect = { ...plan.dialect, key: plan.lowered?.dialect.key ?? "" };
  const validators = emitValidators(plan);
  return [
    "// Generated by `mantle generate`. Do not edit by hand.",
    'import type { GeneratedRuntime } from "@aotter/mantle";',
    ...(validators ? ['import { jsonSchemaValidator } from "@aotter/mantle";'] : []),
    "",
    "export const generated: GeneratedRuntime = {",
    `  fingerprint: ${JSON.stringify(plan.fingerprint)},`,
    `  mantle: ${JSON.stringify(MANTLE_VERSION)},`,
    `  dialect: ${JSON.stringify(dialect)},`,
    ...(validators ? [`  validators: ${validators},`] : []),
    "};", "",
  ].join("\n");
}
